using System;using System.Linq;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;
public static class MotionActionInstall {
 public static void Run(){EditorSceneManager.OpenScene("Assets/Shioka/Scenes/CombatFormulaComparison.unity");var actors=UnityEngine.Object.FindObjectsByType<TrainingFighter>(FindObjectsSortMode.None);foreach(var f in actors){var view=f.GetComponent<ArmoredStaticPoseView>();var c=view.characterProfile;if(c==null||c.characterId!="awari")throw new Exception("Expected Awari");if(c.idleAction!=null&&c.forwardWalkAction!=null)continue;var body=f.GetComponent<TrainingMotor2D>();var hurtProfile=f.hurtboxProfile??f.GetComponent<CombatTestV01>()?.profile?.hurtboxes;if(hurtProfile==null||body==null)throw new Exception("Missing body/hurt profile for "+f.name);var hurt=hurtProfile.regions.Select(r=>{bool whole=r.shape==TrainingHurtboxShape.BodyWhole,upper=r.shape==TrainingHurtboxShape.BodyUpper;float height=body.height,split=Mathf.Min(.75f,height*.6f),bottom=body.center.y-height*.5f,part=whole?height:upper?height-split:split;return new TrainingMotionHurt{partId=r.stableId,center=r.shape==TrainingHurtboxShape.Box?TrainingCoordinates2D.FromLegacy(r.center):new Vector2(0,bottom+(!whole&&upper?split:0)+part*.5f),size=r.shape==TrainingHurtboxShape.Box?TrainingCoordinates2D.HalfSize(r.size):new Vector2(body.radius*2,part)};}).ToArray();c.idleAction=Make("Idle",c.IdleSprite,hurt);c.forwardWalkAction=Make("ForwardWalk",c.ForwardSprite,hurt);c.idle=null;c.forward=null;EditorUtility.SetDirty(c);AssetDatabase.SaveAssetIfDirty(c);Debug.Log("MOTION_INSTALL "+c.name+" body "+body.height+" radius "+body.radius+" parts "+hurt.Length);}AssetDatabase.SaveAssets();}
 static TrainingMotionAction Make(string name,Sprite sprite,TrainingMotionHurt[] hurt){string path="Assets/Shioka/調整Data/Fighter/Awari/Move/"+name+"/"+name+".asset";if(AssetDatabase.LoadMainAssetAtPath(path)!=null)throw new Exception("Refuse overwrite "+path);var action=ScriptableObject.CreateInstance<TrainingMotionAction>();action.poses=new[]{new TrainingMotionPose{sprite=sprite,holdFrames=1,hurt=hurt.Select(h=>new TrainingMotionHurt{partId=h.partId,center=h.center,size=h.size}).ToArray()}};if(!action.Validate(out var error))throw new Exception(error);AssetDatabase.CreateAsset(action,path);return action;}
}
